const plateHost = document.getElementById('plates'), stage = document.getElementById('stage'), sheet = document.getElementById('sheet');
const numerals = ['一', '二', '三', '四', '五', '六', '七', '八', '九'];
// 版块之间用滚动切换：页面在内嵌框里，不能用「#锚点」链接（那会让内嵌框去加载外面的整个页面）。
const links = [...document.querySelectorAll('.jump button')], sections = links.map(link => document.getElementById(link.dataset.to));
